/**
 * A Builder manages a single custom widget builder popup window.
 * It opens the window, listens for messages coming from it and exposes helpers
 * to communicate with, focus and tear down the window.
 */
export class Builder implements IBuilder {
  // The popup window that hosts the custom widget builder
  builderWindow: Window | null;

  // Map of message type -> list of callbacks registered for that type
  private onMessageMap = new Map<string, MessageCallback[]>();

  // Reference to the bound message handler so it can be removed later
  private messageHandler: (event: MessageEvent) => void;

  constructor() {
    this.builderWindow = window.open(
      `${window.location.pathname}/builder`,
      "_blank",
    );

    this.messageHandler = (event: MessageEvent) => {
      if (event.source === this.builderWindow) {
        const handlerList = this.onMessageMap.get(event.data?.type);

        if (handlerList) {
          handlerList.forEach((callback) => callback(event.data));
        }
      }
    };

    window.addEventListener("message", this.messageHandler);
  }

  onMessage = (type: string, callback: MessageCallback) => {
    let eventHandlerList = this.onMessageMap.get(type);

    if (eventHandlerList) {
      eventHandlerList.push(callback);
    } else {
      eventHandlerList = [callback];
      this.onMessageMap.set(type, eventHandlerList);
    }

    return () => {
      const handlerList = this.onMessageMap.get(type);

      if (handlerList) {
        const index = handlerList.indexOf(callback);

        if (index > -1) {
          handlerList.splice(index, 1);
        }
      }
